    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>Result</returns>
    boolean salesLine_validateWrite(SalesLine _salesLine, InventDim _inventDim)
    {
        FormDataSource  metSalesLineStdDS   = FormDataUtil::getFormDataSource(_salesLine);
        FormDataSource  metInventDimDS      = FormDataUtil::getFormDataSource(_inventDim);
        FormRun         metFormRun          = metSalesLineStdDS.formRun();        
        boolean         ret;
        if(metFormRun.form().name() == formStr(SalesTable))
        {            
            FormDataSource  metSalesLineDs      = metFormRun.dataHelper().FindDataSource(formDataSourceStr(SalesTable, METSalesLine));
            METSalesLine    metSalesLineLocal   = metSalesLineDs.cursor();

            // MPJ-21310
            if(metSalesLineLocal.SubstituteOriginalItemID == METConstants::emptyString)
            {
                METSalesItemSubstitution metSalesItemSubstitution = METSalesItemSubstitution::construct(
                    _salesLine,
                    metSalesLineLocal,
                    _inventDim);
                metSalesItemSubstitution.interactive                 = true;
                metSalesItemSubstitution.runReservationTimeChecks    = (_salesLine.Reservation == ItemReservation::Automatic);
                ret = metSalesItemSubstitution.run();
            
                if(ret && metSalesItemSubstitution.getNewLineCreated())
                {
                    _salesLine = metSalesItemSubstitution.parmSalesLine();
                    _inventDim = metSalesItemSubstitution.parmInventDim();

                    metSalesLineStdDS.cursor().data(metSalesItemSubstitution.parmSalesLine());
                    metInventDimDS.cursor().data(metSalesItemSubstitution.parmInventDim());
                    metSalesLineDs.cursor().data(metSalesItemSubstitution.parmMetSalesLine());
                }
            }
        }

        ret = next salesLine_validateWrite(_salesLine, _inventDim) && ret;
    
        return ret;
    }

/// <summary>
/// CoC
/// </summary>
/// <returns>Result</returns>
public boolean useAlternativeItem()
{
    boolean ret = next useAlternativeItem();
    
    // MPJ-21310
    if(CustParameters::find().METSubstitutionEnabled)
    {
        ret = false;
    }
    return ret;
}
